import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIODeviceClosed

PINS = [2, 3, 4]
INTERVAL = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    outputs = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                dev.off()
                outputs.append(dev)
            except GPIODeviceError as exc:
                print(f"Error: could not initialize GPIO {pin}: {exc}", file=sys.stderr)
                for dev in outputs:
                    try:
                        dev.close()
                    except GPIODeviceClosed:
                        pass
                sys.exit(1)

        print(f"Initialized GPIO {PINS} as outputs (OFF).")

        while _running:
            for i, dev in enumerate(outputs):
                try:
                    dev.off()
                    print(f"GPIO {PINS[i]} -> OFF")
                except GPIODeviceClosed:
                    print(f"Error: GPIO {PINS[i]} was closed unexpectedly.", file=sys.stderr)
                    _running = False
                    break
            if _running:
                time.sleep(INTERVAL)

    finally:
        for dev in outputs:
            try:
                dev.close()
            except GPIODeviceClosed:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

