import signal
import sys
import time

from gpiozero import PWMOutputDevice

# PCA9685 channel 0; 4096 steps, 20 ms period
CHANNEL = 0
STEPS = 4096
PERIOD = 0.02

running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_channel(channel: int) -> int:
    """Read and validate a PCA9685 channel value.

    Returns the 12-bit value (0-4095) or None if the read fails.
    """
    try:
        value = channel.value * STEPS
        if not (0 <= value <= STEPS):
            print(f"Warning: channel value {value} out of range [0, {STEPS}]", file=sys.stderr)
            return None
        return int(value)
    except Exception as exc:
        print(f"Warning: failed to read channel {channel}: {exc}", file=sys.stderr)
        return None


def main() -> int:
    global running

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        channel = PWMOutputDevice(CHANNEL, frequency=int(1.0 / PERIOD))
    except Exception as exc:
        print(f"Error: failed to initialize PWMOutputDevice on channel {CHANNEL}: {exc}", file=sys.stderr)
        return 1

    try:
        while running:
            val = read_channel(channel)
            if val is not None:
                print(f"Channel {CHANNEL} = {val}")
            time.sleep(PERIOD)
    finally:
        try:
            channel.close()
        except Exception:
            pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

