import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
READ_TIMEOUT = 2.0
LOOP_INTERVAL = 5.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_device_data(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None
    if not raw:
        print("Warning: no data received (timeout).", file=sys.stderr)
        return None
    data = raw.decode('ascii', errors='replace').strip()
    if not data:
        return None
    return data

def process_data(data):
    try:
        return int(data)
    except ValueError:
        print(f"Invalid data received (not an integer): '{data}'", file=sys.stderr)
        return None

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=115200,
            timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            data = read_device_data(ser)
            if data is not None:
                processed = process_data(data)
                if processed is not None:
                    print(f"Received: {processed}")
            if _running:
                time.sleep(LOOP_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN_1 = 20
PIN_2 = 21
INTERVAL = 0.5

running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_state(pin: int) -> int:
    """Read a state from the user (validated as 0 or 1)."""
    while running:
        try:
            raw = input(f"Enter state for GPIO {pin} (0 or 1): ")
        except EOFError:
            return None
        try:
            state = int(raw)
        except ValueError:
            print("Invalid input. Please enter 0 or 1.")
            continue
        if state in (0, 1):
            return state
        print("Invalid input. Please enter 0 or 1.")
    return None


def main() -> int:
    global running

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        dev1 = OutputDevice(PIN_1)
        dev2 = OutputDevice(PIN_2)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        return 1

    try:
        while running:
            s1 = read_state(PIN_1)
            if s1 is None:
                break
            try:
                dev1.value = bool(s1)
            except GPIOZeroError as exc:
                print(f"Error writing GPIO {PIN_1}: {exc}", file=sys.stderr)
                break

            s2 = read_state(PIN_2)
            if s2 is None:
                break
            try:
                dev2.value = bool(s2)
            except GPIOZeroError as exc:
                print(f"Error writing GPIO {PIN_2}: {exc}", file=sys.stderr)
                break

            print(f"GPIO {PIN_1} set to {s1}, GPIO {PIN_2} set to {s2}")

            time.sleep(INTERVAL)
    finally:
        try:
            dev1.close()
        except Exception:
            pass
        try:
            dev2.close()
        except Exception:
            pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

