import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

TRIGGER_PIN = 17
ECHO_PIN = 22
CYCLES = 5
INTERVAL = 50  # seconds

running = True

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        sensor = DistanceSensor(echo=ECHO_PIN, trigger=TRIGGER_PIN, max_distance=4.0)
    except GPIOZeroError as exc:
        print(f"Failed to initialize HC-SR04: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(1, CYCLES + 1):
            if not running:
                break
            try:
                distance = sensor.distance * 100  # meters -> cm
                print(f"Cycle {i}/{CYCLES}: {distance:.1f} cm")
            except DeviceClosed:
                print(f"Cycle {i}/{CYCLES}: sensor closed unexpectedly", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Cycle {i}/{CYCLES}: read error: {exc}", file=sys.stderr)
                break
            if i < CYCLES and running:
                time.sleep(INTERVAL)
    finally:
        try:
            sensor.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

