import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# BCM pin numbers for the digital outputs
OUTPUT_PINS = (17, 27)

# Validate each reading before applying it
def validate_reading(value: str) -> bool:
    """Return True if the string is a non-empty alphanumeric token."""
    return bool(value and value.isalnum())


def apply_output(pin: int, value: str) -> None:
    """Apply the validated value to the output pin and report the state."""
    try:
        device = OutputDevice(pin)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to initialise GPIO {pin}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        if value == "ON":
            device.on()
        elif value == "OFF":
            device.off()
        else:
            print(f"Error: invalid value '{value}' for pin {pin}", file=sys.stderr)
            return

        print(f"Pin {pin} set to {value}")
    finally:
        device.close()


def main() -> None:
    # Graceful shutdown on SIGINT / SIGTERM
    def _shutdown(signum, frame):
        print("\nShutdown signal received, exiting...")
        sys.exit(0)

    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    try:
        while True:
            for pin in OUTPUT_PINS:
                try:
                    reading = input(f"Enter value for pin {pin} (ON/OFF): ")
                except EOFError:
                    print("\nEnd of input, exiting...")
                    sys.exit(0)

                if validate_reading(reading):
                    apply_output(pin, reading)
                else:
                    print(f"Error: invalid input for pin {pin}", file=sys.stderr)

            time.sleep(60)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

