import signal
import sys
import time
import board
import adafruit_dht

# Map BCM pin numbers to board pins
BCM_TO_BOARD = {
    4: board.D4,
    5: board.D5,
    17: board.D17,
    23: board.D23,
}

# Validate that every BCM pin is supported
for bcm in [4, 5, 17, 23]:
    if bcm not in BCM_TO_BOARD:
        raise ValueError(f"Unsupported BCM pin: {bcm}")

# Initialize DHT22 sensors
sensors = {}
for bcm, pin in BCM_TO_BOARD.items():
    try:
        sensors[bcm] = adafruit_dht.DHT22(pin, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on BCM {bcm}: {exc}", file=sys.stderr)
        sensors[bcm] = None

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

def cleanup():
    for bcm, sensor in sensors.items():
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass

try:
    while running:
        for bcm, sensor in sensors.items():
            if sensor is None:
                print(f"BCM {bcm}: sensor not initialized")
                continue
            try:
                temperature = sensor.temperature
                humidity = sensor.humidity
                if temperature is None or humidity is None:
                    print(f"BCM {bcm}: reading failed (None)")
                elif not (0 <= humidity <= 100 and -40 <= temperature <= 80):
                    print(f"BCM {bcm}: reading out of range "
                          f"(T={temperature}C, H={humidity}%)")
                else:
                    print(f"BCM {bcm}: T={temperature:.1f}C  H={humidity:.1f}%")
            except RuntimeError as exc:
                # DHT22 checksum / timing errors are common; log and continue
                print(f"BCM {bcm}: read error: {exc}")
            except Exception as exc:
                print(f"BCM {bcm}: unexpected error: {exc}", file=sys.stderr)

        if running:
            time.sleep(60)
finally:
    cleanup()

