import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOUnavailableError, GPIOZeroError

PINS = [17, 18, 27]
INTERVAL = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    outputs = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                dev.off()
                outputs.append(dev)
            except GPIOUnavailableError:
                print(f"Error: GPIO {pin} is unavailable or already in use.", file=sys.stderr)
                for dev in outputs:
                    dev.close()
                sys.exit(1)
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                for dev in outputs:
                    dev.close()
                sys.exit(1)

        print(f"Initialized outputs: {PINS}")

        while _running:
            for i, dev in enumerate(outputs):
                try:
                    dev.on()
                    print(f"GPIO {PINS[i]} -> ON")
                except GPIOZeroError as exc:
                    print(f"Error writing GPIO {PINS[i]}: {exc}", file=sys.stderr)

            for i, dev in enumerate(outputs):
                try:
                    dev.off()
                    print(f"GPIO {PINS[i]} -> OFF")
                except GPIOZeroError as exc:
                    print(f"Error writing GPIO {PINS[i]}: {exc}", file=sys.stderr)

            for _ in range(INTERVAL):
                if not _running:
                    break
                time.sleep(1)

    finally:
        for dev in outputs:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

