import signal
import sys
import time

from gpiozero import PWMOutputDevice

PINS = [4, 17, 22, 27]

running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_and_apply(pwm):
    """Read a value from stdin and apply it to the PWM device.

    Returns True on success, False if the read failed or the value was
    invalid.
    """
    try:
        raw = input("Enter PWM value (0-100): ")
    except EOFError:
        return False
    except KeyboardInterrupt:
        return False

    try:
        value = float(raw)
    except ValueError:
        print(f"Invalid input '{raw}': must be a numeric value.")
        return True

    if not 0.0 <= value <= 100.0:
        print(f"Value out of range: {value}. Must be between 0 and 100.")
        return True

    try:
        pwm.value = value / 100.0
        print(f"PWM set to {value}% on pin {pwm.pin.number}")
    except Exception as exc:
        print(f"Failed to set PWM on pin {pwm.pin.number}: {exc}")

    return True


def main():
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    pwms = []
    try:
        for pin in PINS:
            try:
                pwm = PWMOutputDevice(pin)
                pwms.append(pwm)
                print(f"PWM initialized on GPIO {pin}")
            except Exception as exc:
                print(f"Failed to initialize PWM on GPIO {pin}: {exc}")
                return 1

        while running:
            for pwm in pwms:
                if not read_and_apply(pwm):
                    break
            if not running:
                break
            time.sleep(1)

    finally:
        for pwm in pwms:
            try:
                pwm.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

