import signal
import sys
import time

import serial

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
READ_TIMEOUT = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_sensor_data(serial_connection):
    """Read one line from the serial port and return it stripped, or None on error."""
    try:
        raw = serial_connection.readline()
    except serial.SerialException as exc:
        print(f"Error reading from serial port: {exc}", file=sys.stderr)
        return None

    if not raw:
        print("Warning: no data received from serial port (timeout).", file=sys.stderr)
        return None

    try:
        return raw.decode("ascii", errors="replace").strip()
    except Exception as exc:
        print(f"Error decoding serial data: {exc}", file=sys.stderr)
        return None


def process_sensor_data(data):
    """Validate and print the sensor reading. Returns True if valid, False otherwise."""
    if not data:
        print("Warning: empty data received.", file=sys.stderr)
        return False

    try:
        value = float(data)
    except ValueError:
        print(f"Warning: invalid data received (not a float): '{data}'.", file=sys.stderr)
        return False

    if not (-20.0 <= value <= 50.0):
        print(f"Warning: value {value} out of range [-20.0, 50.0].", file=sys.stderr)
        return False

    print(f"Sensor Value: {value}")
    return True


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    serial_connection = None
    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
        )
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud.")

        if not _running:
            return

        sensor_data = read_sensor_data(serial_connection)
        if sensor_data is not None:
            process_sensor_data(sensor_data)

    except serial.SerialException as exc:
        print(f"Error opening or using serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if serial_connection is not None and serial_connection.is_open:
            try:
                serial_connection.close()
                print("Serial port closed.")
            except Exception as exc:
                print(f"Error closing serial port: {exc}", file=sys.stderr)


if __name__ == "__main__":
    main()

