def _validate(value: str) -> bool:
    """Return True if the input string is a valid 0/1 or H/L."""
    return value.strip().upper() in ('0', '1', 'H', 'L')


def _parse(value: str) -> int:
    """Map '0'/'1'/'H'/'L' to gpiozero.OutputDevice.value (True/False)."""
    return {'0': False, '1': True, 'H': True, 'L': False}[value.strip().upper()]


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pin17 = OutputDevice(PIN_17)
        pin22 = OutputDevice(PIN_22)
    except GPIOZeroError as exc:
        print(f'Error: failed to initialize GPIO pins: {exc}', file=sys.stderr)
        return 1

    try:
        while _running:
            try:
                raw = input('Enter state for GPIO 17 (0/1/H/L): ')
            except EOFError:
                print('\nEOF received; exiting.')
                break

            if not _validate(raw):
                print('Invalid input. Use 0, 1, H, or L.')
                continue

            try:
                state = _parse(raw)
            except Exception as exc:
                print(f'Error: failed to parse input: {exc}')
                continue

            try:
                pin17.value = state
                pin22.value = state
            except GPIOZeroError as exc:
                print(f'Error: failed to write GPIO: {exc}')
                continue

            print(f'GPIO 17 -> {state}, GPIO 22 -> {state}')

            time.sleep(POLL_INTERVAL)

    finally:
        try:
            pin17.close()
        except Exception:
            pass
        try:
            pin22.close()
        except Exception:
            pass

    return 0


if __name__ == '__main__':
    sys.exit(main())

