import signal
import sys
import time
import board
import adafruit_dht

# DHT22 data pins (BCM numbering)
DATA_PINS = [board.D4, board.D17]

# Global sensor handle so the signal handler can release it
_sensor = None


def _cleanup(signum=None, frame=None):
    """Release hardware resources on exit or signal."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None
    if signum is not None:
        sys.exit(0)


def main():
    global _sensor

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    # Initialise DHT22 sensors
    sensors = []
    for pin in DATA_PINS:
        try:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            sensors.append(sensor)
        except Exception as exc:
            print(f"Error: failed to initialise DHT22 on pin {pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)

    _sensor = sensors[0] if sensors else None

    try:
        while True:
            for sensor in sensors:
                try:
                    temperature = sensor.temperature
                    humidity = sensor.humidity

                    # DHT22 validity check: humidity in [0, 100], temp in [-40, 80]
                    if humidity is None or temperature is None:
                        print(f"Error: DHT22 returned None (sensor on pin {sensor.pin.name})")
                    elif not (0 <= humidity <= 100):
                        print(f"Error: DHT22 humidity out of range: {humidity} (sensor on pin {sensor.pin.name})")
                    elif not (-40 <= temperature <= 80):
                        print(f"Error: DHT22 temperature out of range: {temperature} (sensor on pin {sensor.pin.name})")
                    else:
                        print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} % (sensor on pin {sensor.pin.name})")

                except RuntimeError as exc:
                    # DHT22 checksum or timing errors are common; log and continue
                    print(f"Warning: DHT22 read error on pin {sensor.pin.name}: {exc}")
                except Exception as exc:
                    print(f"Error: unexpected DHT22 failure on pin {sensor.pin.name}: {exc}", file=sys.stderr)

            time.sleep(5)

    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)


if __name__ == "__main__":
    main()

