import signal
import sys
import time

from smbus2 import SMBus

# TSL2561 constants
TSL2561_ADDR = 0x29
TSL2561_COMMAND_BIT = 0xA0
TSL2561_REGISTER_ENABLE = 0x00
TSL2561_REGISTER_CONTROL = 0x01
TSL2561_REGISTER_CHAN0_LOW = 0x14
TSL2561_REGISTER_CHAN1_LOW = 0x16
TSL2561_REGISTER_CHAN0_HIGH = 0x12
TSL2561_REGISTER_CHAN1_HIGH = 0x13
TSL2561_REGISTER_DEVICE_ID = 0x12

TSL2561_POWER_ON = 0x03
TSL2561_INTEGRATIONTIME_101MS = 0x00
TSL2561_GAIN_16X = 0x10


class TSL2561:
    def __init__(self, bus_number=1, address=TSL2561_ADDR):
        self.address = address
        self.bus = None
        try:
            self.bus = SMBus(bus_number)
        except OSError as e:
            raise RuntimeError(f"Failed to open I2C bus {bus_number}: {e}") from e

        # Verify device identity
        try:
            dev_id = self._read_register(TSL2561_REGISTER_DEVICE_ID)
        except OSError as e:
            self.close()
            raise RuntimeError(f"Failed to read device ID: {e}") from e

        if dev_id != 0x50:
            self.close()
            raise RuntimeError(
                f"Invalid device ID: 0x{dev_id:02X}. Expected 0x50 for TSL2561."
            )

        # Power on and configure integration time / gain
        try:
            self._write_register(TSL2561_REGISTER_ENABLE, TSL2561_POWER_ON)
            self._write_register(
                TSL2561_REGISTER_CONTROL,
                TSL2561_INTEGRATIONTIME_101MS | TSL2561_GAIN_16X,
            )
        except OSError as e:
            self.close()
            raise RuntimeError(f"Failed to configure TSL2561: {e}") from e

    def _write_register(self, register, value):
        self.bus.write_byte_data(self.address, register | TSL2561_COMMAND_BIT, value)

    def _read_register(self, register):
        return self.bus.read_byte_data(self.address, register | TSL2561_COMMAND_BIT)

    def _read_word(self, register):
        data = self.bus.read_i2c_block_data(self.address, register | TSL2561_COMMAND_BIT, 2)
        return data[0] | (data[1] << 8)

    def get_full_spectrum(self):
        return self._read_word(TSL2561_REGISTER_CHAN0_LOW)

    def get_infrared(self):
        return self._read_word(TSL2561_REGISTER_CHAN1_LOW)

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None


def main():
    sensor = None
    running = True

    def handle_signal(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        sensor = TSL2561()
        while running:
            try:
                full = sensor.get_full_spectrum()
                ir = sensor.get_infrared()
                print(f"Full Spectrum: {full}, Infrared: {ir}")
            except OSError as e:
                print(f"Read error: {e}", file=sys.stderr)
            time.sleep(1)
    except RuntimeError as e:
        print(f"Initialization error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if sensor is not None:
            sensor.close()


if __name__ == "__main__":
    main()

import signal
import sys
import time

import board
import adafruit_dht

# Map BCM pin number to board pin object
BCM_TO_BOARD = {
    4: board.D4,
    7: board.D7,
    11: board.D11,
    17: board.D17,
}

# Global list of DHT22 objects for cleanup
_sensors = []


def _cleanup(signum=None, frame=None):
    """Release all DHT22 resources on exit."""
    for s in _sensors:
        try:
            s.exit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def read_dht22(pin_bcms):
    """
    Read temperature and humidity from each DHT22 on the given BCM pins.
    Returns a list of (pin, temperature, humidity) tuples.
    """
    results = []
    for bcm in pin_bcms:
        try:
            sensor = adafruit_dht.DHT22(BCM_TO_BOARD[bcm], use_pulseio=False)
            _sensors.append(sensor)
        except Exception as exc:
            results.append((bcm, None, None, f"init error: {exc}"))
            continue

        try:
            temperature = sensor.temperature
            humidity = sensor.humidity

            # DHT22 validity range: -40–80 °C, 0–100 %RH
            if temperature is None or humidity is None:
                results.append((bcm, None, None, "read returned None"))
            elif not (-40 <= temperature <= 80) or not (0 <= humidity <= 100):
                results.append((bcm, None, None, f"out-of-range: T={temperature} H={humidity}"))
            else:
                results.append((bcm, temperature, humidity, None))
        except RuntimeError as exc:
            # Common transient errors: checksum, timeout, device not responding
            results.append((bcm, None, None, f"read error: {exc}"))
        except Exception as exc:
            results.append((bcm, None, None, f"unexpected error: {exc}"))

    return results


def main():
    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    pins = [4, 7, 11, 17]
    while True:
        results = read_dht22(pins)

        for bcm, temp, hum, err in results:
            if err:
                print(f"DHT22 BCM {bcm}: ERROR - {err}")
            else:
                print(f"DHT22 BCM {bcm}: T={temp:.1f} C  H={hum:.1f} %")

        time.sleep(5)


if __name__ == "__main__":
    main()

