import sys
import signal
import time

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)


class CameraApp:
    """Captures an image with picamera2 and saves it to a file."""

    def __init__(self, filename="capture.jpg"):
        self.filename = filename
        self.camera = None
        self._running = True

    def _handle_signal(self, signum, frame):
        print(f"\nReceived signal {signum}, shutting down...", file=sys.stderr)
        self._running = False

    def _cleanup(self):
        if self.camera is not None:
            try:
                self.camera.close()
            except Exception as e:
                print(f"Warning: error closing camera: {e}", file=sys.stderr)
            finally:
                self.camera = None

    def run(self):
        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGTERM, self._handle_signal)

        try:
            self.camera = Picamera2()
        except Exception as e:
            print(f"Error: failed to initialize camera: {e}", file=sys.stderr)
            return 1

        try:
            self.camera.start()
            time.sleep(1)  # Allow auto-exposure / AWB to settle

            if not self._running:
                return 130

            try:
                self.camera.capture_file(self.filename)
            except Exception as e:
                print(f"Error: failed to capture image: {e}", file=sys.stderr)
                return 1

            print(f"Image saved to {self.filename}")
            return 0
        finally:
            self._cleanup()


if __name__ == "__main__":
    app = CameraApp()
    sys.exit(app.run())

