    4: board.D4,
    17: board.D17,
    18: board.D18,
    22: board.D22,
    23: board.D23,
    27: board.D27,
}

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

sensors = {}

try:
    for bcm_pin in BCM_TO_BOARD:
        board_pin = BCM_TO_BOARD[bcm_pin]
        try:
            sensors[bcm_pin] = adafruit_dht.DHT22(board_pin, use_pulseio=False)
        except Exception as e:
            print(f"Failed to initialize DHT22 on BCM pin {bcm_pin}: {e}", file=sys.stderr)
            sensors[bcm_pin] = None

    cycles = 0
    while running and cycles < 3:
        for bcm_pin in sensors:
            sensor = sensors[bcm_pin]
            if sensor is None:
                print(f"BCM {bcm_pin}: init failed")
                continue
            try:
                temperature = sensor.temperature
                humidity = sensor.humidity
