import time
import signal
import sys
import board
import adafruit_dht

# Global list to track DHT22 sensors for cleanup
_sensors = []

def cleanup(signum=None, frame=None):
    """Release all DHT22 sensors and exit cleanly."""
    for sensor in _sensors:
        try:
            sensor.exit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    # Register signal handlers for clean exit on SIGINT and SIGTERM
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize DHT22 sensors on the specified GPIO pins
    # board.D4, board.D17, board.D27 correspond to BCM GPIO 4, 17, 27
    try:
        sensor_pins = [board.D4, board.D17, board.D27]
        for pin in sensor_pins:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            _sensors.append(sensor)
    except Exception as e:
        print(f"Failed to initialize DHT22 sensors: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while True:
            for idx, sensor in enumerate(_sensors):
                try:
                    temperature = sensor.temperature
                    humidity = sensor.humidity
                    if temperature is not None and humidity is not None:
                        print(f"Sensor {idx}: Temp={temperature:.1f}C, Humidity={humidity:.1f}%")
                    else:
                        print(f"Sensor {idx}: Read failed (None)")
                except RuntimeError as e:
                    # DHT22 often throws transient read errors; log and continue
                    print(f"Sensor {idx}: Read error: {e}")
                except Exception as e:
                    print(f"Sensor {idx}: Unexpected error: {e}", file=sys.stderr)
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

