import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
I2C_ADDR = 0x76
REG_ID = 0xD0
REG_DATA = 0xF7
READ_LEN = 8
INTERVAL_S = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _check_id(bus):
    try:
        return bus.read_byte_data(I2C_ADDR, REG_ID) == 0x60
    except OSError:
        return False


def _read_raw(bus):
    write_msg = i2c_msg.write(I2C_ADDR, [REG_DATA])
    read_msg = i2c_msg.read(I2C_ADDR, READ_LEN)
    bus.i2c_rdwr(write_msg, read_msg)
    data = list(read_msg)
    if len(data) != READ_LEN:
        return None
    raw = (data[1] << 12) | (data[2] << 4) | (data[3] >> 4)
    return raw


def _validate(raw):
    if raw is None:
        return False
    if raw < 32768 or raw > 524287:
        return False
    return True


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        if not _check_id(bus):
            print(f"Error: no BME280 found at 0x{I2C_ADDR:02X}", file=sys.stderr)
            sys.exit(1)

        while _running:
            raw = _read_raw(bus)
            if _validate(raw):
                print(f"BME280 reading: {raw}")
            else:
                print("Warning: invalid reading from BME280", file=sys.stderr)
            for _ in range(INTERVAL_S):
                if not _running:
                    break
                time.sleep(1)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

import signal
import sys
import time

import smbus2

I2C_BUS = 1
I2C_ADDR = 0x77
READ_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _check_valid(data):
    if data is None or len(data) < 1:
        return False
    status = data[0]
    if status & 0x10:
        return False
    if status & 0x20:
        return False
    return True


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                data = bus.read_i2c_block_data(I2C_ADDR, 0x1D, 1)
            except OSError as exc:
                print(f"Error: I2C read failed from 0x{I2C_ADDR:02X}: {exc}", file=sys.stderr)
                sys.exit(1)

            if not _check_valid(data):
                print("Warning: BME680 returned invalid data (heater or gas status).", file=sys.stderr)

            print(f"BME680 reading: {data[0]}")

            time.sleep(READ_INTERVAL_S)
    finally:
        bus.close()


