PINS = [4, 17, 18, 22, 23, 24, 25, 27]

running = True
devices = []


def handle_signal(signum, frame):
    global running
    running = False


def apply_state(device, state):
    try:
        device.on() if state else device.off()
        print(f"GPIO {device.pin.number} -> {'ON' if state else 'OFF'}")
    except GPIOZeroError as exc:
        print(f"Error setting GPIO {device.pin.number}: {exc}", file=sys.stderr)


def main():
    global devices
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        devices = [OutputDevice(pin) for pin in PINS]
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            for device in devices:
                apply_state(device, True)
            for device in devices:
                apply_state(device, False)
            time.sleep(0.001)
    finally:
        for device in devices:
            try:
                device.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


