import signal
import sys
import time

import board
import busio
from adafruit_mcp3xxx.mcp3008 import MCP3008

MIN_VALID = 0
MAX_VALID = 1023

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_adc_channel(adc, channel):
    """Read and validate a single ADC channel; return the value or None."""
    if not 0 <= channel <= 7:
        print(f"Error: channel {channel} out of range (0-7)", file=sys.stderr)
        return None
    try:
        value = adc.read(channel)
    except Exception as exc:
        print(f"Error reading ADC channel {channel}: {exc}", file=sys.stderr)
        return None
    if not (MIN_VALID <= value <= MAX_VALID):
        print(f"Error: ADC value {value} out of range ({MIN_VALID}-{MAX_VALID})", file=sys.stderr)
        return None
    return value

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    i2c = None
    adc = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        adc = MCP3008(i2c, differential=False)

        channel = 0
        value = read_adc_channel(adc, channel)
        if value is not None:
            print(f"ADC Channel {channel} Raw Value: {value}")

    except Exception as exc:
        print(f"Initialization or runtime error: {exc}", file=sys.stderr)
    finally:
        if adc is not None:
            try:
                adc.deinit()
            except Exception:
                pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass

if __name__ == "__main__":
    main()

import signal
import sys
import time

import smbus2

I2C_BUS = 1
BMP280_ADDR = 0x76
REG_CHIP_ID = 0xD0
EXPECTED_CHIP_ID = 0x58
REG_PRESS_MSB = 0xF7

running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_chip_id(bus):
    try:
        return bus.read_byte_data(BMP280_ADDR, REG_CHIP_ID)
    except OSError as exc:
        print(f"Error: cannot read chip ID from BMP280 at 0x{BMP280_ADDR:02X}: {exc}", file=sys.stderr)
        return None


def read_pressure(bus):
    try:
        data = bus.read_i2c_block_data(BMP280_ADDR, REG_PRESS_MSB, 3)
        raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
        return raw / 100.0
    except OSError as exc:
        print(f"Error: failed to read pressure: {exc}", file=sys.stderr)
        return None


def main():
    global running

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    chip_id = read_chip_id(bus)
    if chip_id is None:
        bus.close()
        sys.exit(1)

    if chip_id != EXPECTED_CHIP_ID:
        print(f"Error: unexpected chip ID 0x{chip_id:02X} (expected 0x{EXPECTED_CHIP_ID:02X})", file=sys.stderr)
        bus.close()
        sys.exit(1)

    print("BMP280 detected. Reading pressure every 5 s (Ctrl+C to stop).")

    try:
        while running:
            pressure = read_pressure(bus)
            if pressure is not None:
                print(f"Pressure: {pressure:.2f} hPa")
            time.sleep(5)
    finally:
        bus.close()
        print("\nI2C bus released. Exiting.")


if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
LOOP_DELAY = 0.1

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_sensor_data(serial_connection):
    try:
        raw = serial_connection.readline()
        if not raw:
            return None
        data = raw.decode('ascii', errors='replace').strip()
        if not data:
            return None
        return data
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"I/O error: {e}", file=sys.stderr)
        return None

def process_sensor_data(data):
    try:
        return int(data)
    except ValueError:
        print(f"Invalid data received: {data}", file=sys.stderr)
        return None

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            sensor_data = read_sensor_data(serial_connection)
            if sensor_data is not None:
                processed_data = process_sensor_data(sensor_data)
                if processed_data is not None:
                    print(processed_data)
            time.sleep(LOOP_DELAY)
    finally:
        if serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

