import time
import signal
import sys
from w1thermsensor import W1ThermSensor, SensorNotReadyError, NoSensorFoundError

# Global flag for graceful shutdown
_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    # Register signal handlers for clean exit on SIGINT / SIGTERM
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize the DS18B20 sensor on GPIO 4 (w1thermsensor uses the
    # 1-Wire bus by default; no GPIO pin is specified explicitly here).
    try:
        sensor = W1ThermSensor()
    except NoSensorFoundError:
        print("Error: No DS18B20 sensor found on the 1-Wire bus.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: Failed to initialize DS18B20 sensor: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                temperature = sensor.get_temperature()

                # Validate the reading (w1thermsensor returns None on error)
                if temperature is None:
                    print("Warning: Sensor returned None; retrying...", file=sys.stderr)
                else:
                    print(f"Temperature: {temperature:.2f} C")

            except SensorNotReadyError:
                print("Warning: Sensor not ready yet; retrying...", file=sys.stderr)
            except Exception as e:
                print(f"Warning: Unexpected read error: {e}", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < 5.0:
                time.sleep(0.1)
                slept += 0.1

    finally:
        # Release the sensor resource on every exit path
        try:
            sensor.cleanup()
        except Exception:
            pass

if __name__ == "__main__":
    main()

