from gpiozero import OutputDevice

GPIO_PIN = 17

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

def apply_state(device, state):
    """Apply a validated state to the GPIO output and report it."""
    if state == 1:
        device.on()
    else:
        device.off()
    print(f"GPIO {GPIO_PIN} set to {'HIGH' if state == 1 else 'LOW'}")

def main():
    device = None
    try:
        device = OutputDevice(GPIO_PIN)
        apply_state(device, 1)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if device is not None:
            device.close()

if __name__ == "__main__":
    main()

import time
import signal
import sys
from picamera2 import Picamera2

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

camera = None
try:
    camera = Picamera2()
    camera.start()
    for i in range(5):
        if not running:
            break
        filename = f"image_{i}.jpg"
        try:
            camera.capture_file(filename)
            print(f"Image saved: {filename}")
        except Exception as e:
            print(f"Error capturing image: {e}")
        if i < 4:
            time.sleep(0.5)
except Exception as e:
    print(f"Camera error: {e}")
finally:
    if camera is not None:
        try:
            camera.stop()
        except Exception:
            pass
    sys.exit(0)

