import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOUnavailableError, GPIODeviceError

OUTPUT_PIN = 18
VALID_STATES = {"on", "off"}

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def set_output(pin: int, state: str) -> int:
    if state not in VALID_STATES:
        print(f"Error: invalid state '{state}'. Use 'on' or 'off'.", file=sys.stderr)
        return 2

    try:
        device = OutputDevice(pin)
    except GPIOUnavailableError as exc:
        print(f"Error: GPIO {pin} is unavailable: {exc}", file=sys.stderr)
        return 1
    except GPIODeviceError as exc:
        print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
        return 1

    try:
        if state == "on":
            device.on()
        else:
            device.off()
        print(f"GPIO {pin} set to {state}")
        return 0
    except GPIODeviceError as exc:
        print(f"Error: failed to write to GPIO {pin}: {exc}", file=sys.stderr)
        return 1
    finally:
        device.close()

def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    if len(sys.argv) != 3:
        print("Usage: python script.py <pin> <state>", file=sys.stderr)
        return 2

    pin = int(sys.argv[1])
    state = sys.argv[2].strip().lower()

    if not _running:
        return 130

    return set_output(pin, state)

if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIODeviceClosed

PIN_1 = 2
PIN_2 = 17

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def main():
    global running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        dev1 = OutputDevice(PIN_1)
        dev2 = OutputDevice(PIN_2)
    except GPIODeviceError as exc:
        print(f"Error: could not initialize GPIO {PIN_1}/{PIN_2}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                dev1.on()
                dev2.off()
            except GPIODeviceClosed:
                print("Error: GPIO device closed unexpectedly.", file=sys.stderr)
                break

            print(f"GPIO {PIN_1} set to 1, GPIO {PIN_2} set to 0")
            time.sleep(0.1)
    finally:
        try:
            dev1.close()
        except Exception:
            pass
        try:
            dev2.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
LOOP_DELAY = 0.1

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f"Error: could not open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
                if raw:
                    line = raw.decode('ascii', errors='replace').strip()
                    if line:
                        print(line)
            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                break
            time.sleep(LOOP_DELAY)
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

