            pass
    print("GPIO cleanup done.")

import time
import signal
import sys
import board
import busio
import adafruit_mcp3xxx.mcp3008 as MCP
from adafruit_mcp3xxx.analog_in import AnalogIn

MIN_VALID = 0
MAX_VALID = 1023
SAMPLE_INTERVAL = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_adc_channel(channel):
    """Read and validate a single ADC channel from the MCP3008."""
    try:
        value = adc.value
    except Exception as exc:
        print(f"Error reading ADC channel {channel}: {exc}", file=sys.stderr)
        return None

    if not (MIN_VALID <= value <= MAX_VALID):
        print(f"Warning: ADC channel {channel} reading {value} out of range "
              f"({MIN_VALID}-{MAX_VALID}).", file=sys.stderr)
        return None

    return value

def main():
    global adc
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Failed to initialize I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        adc = MCP.MCP3008(i2c)
    except Exception as exc:
        print(f"Failed to initialize MCP3008 on I2C: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            reading = read_adc_channel(0)
            if reading is not None:
                print(f"ADC Channel 0: {reading}")
            time.sleep(SAMPLE_INTERVAL)
    finally:
        try:
            adc.deinit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

